{
  "case_id": "C03",
  "audience": "School governors and parents",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Why absence matters",
      "narration": "Respiratory illness is the biggest single cause of pupil absence in our primary schools - roughly half of all coded absence days over the winter period.",
      "on_screen": "Title: Air cleaners and pupil absence. Simple pie showing respiratory illness as about half of winter coded absence days.",
      "claim_refs": ["SYN-C03:Background"]
    },
    {
      "beat": "What was tried",
      "narration": "So twenty-two classrooms were given two portable HEPA air cleaners each, while eighteen classrooms in the same authority carried on without them, across one eleven-week winter term.",
      "on_screen": "Two side-by-side classroom icons: 22 classrooms with two HEPA units each vs 18 classrooms with none. Caption: one local authority, 11-week winter term.",
      "claim_refs": ["SYN-C03:Abstract", "SYN-C03:Methods"]
    },
    {
      "beat": "What the numbers showed",
      "narration": "Where the units ran, respiratory absence fell from 4.9 to 3.6 percent of pupil-days. Where they didn't, it fell from 4.7 to 4.4. The gap between those changes is about one percentage point, with a plausible range from 0.1 to 1.9.",
      "on_screen": "Before-and-after bar pairs for both groups, with the difference-in-differences of -1.0 percentage points and its 95% confidence interval -1.9 to -0.1 called out.",
      "claim_refs": ["SYN-C03:Results", "SYN-C03:Abstract"]
    },
    {
      "beat": "How much weight to put on it",
      "narration": "This was not a randomised trial. Schools chose the rooms by available floor space, staff and pupils could see the units, baseline ventilation differed between the two groups, and absence came from office staff's illness codes rather than any test.",
      "on_screen": "Checklist of caveats: rooms chosen by floor space; not blinded; ventilation differed at baseline; outcome is an administrative code, no lab confirmation.",
      "claim_refs": ["SYN-C03:Study design", "SYN-C03:Methods", "SYN-C03:Limitations"]
    },
    {
      "beat": "What it means for us",
      "narration": "So: encouraging, not settled. It is one term in one authority. Worth weighing purchase and running costs against a reduction of around one percentage point - and worth evaluating properly before any wider rollout.",
      "on_screen": "Closing card: Promising, not proven. Weigh costs against roughly one percentage point of pupil-days. Evaluate wider deployment.",
      "claim_refs": ["SYN-C03:Discussion", "SYN-C03:Conclusion", "SYN-C03:Methods"]
    }
  ]
}
